with normalized as (
    select distinct on (inventory_code) *
      from tmp_ecount_inventory_seed
     order by inventory_code, source_row_no
), prepared as (
    select n.*, g.material_group_id,
           concat_ws('?',
               'ECOUNT导入：一级=' || nullif(concat_ws('/', n.ecount_major_code, n.ecount_major_name), ''),
               '二级=' || nullif(concat_ws('/', n.ecount_minor_code, n.ecount_minor_name), ''),
               case when n.legacy_inventory_code is not null then '旧编码=' || n.legacy_inventory_code end,
               case when n.barcode is not null then '条形码=' || n.barcode end,
               case when n.source_created_date is not null then '新增日期=' || n.source_created_date end,
               'source_row=' || n.source_row_no::text,
               'seed_inventory_from_ecount_workbook_20260730'
           ) as generated_remark
      from normalized n
      left join plm_material_group g
        on g.source_system = 'ECOUNT'
       and g.group_level = 1
       and g.ecount_major_code = n.ecount_major_code
       and g.ecount_major_name = n.ecount_major_name
       and g.deleted_flag = 0
)
insert into plm_inventory (
    inventory_code, inventory_name, inventory_type, specification, stock_uom, quantity, supplier_name,
    currency_code, status, remark, material_group_id, is_stock_item, is_purchase_item, is_sales_item,
    created_at, created_by, updated_at, updated_by, deleted_flag
)
select inventory_code, inventory_name, inventory_type, specification, stock_uom, 0, '默认供应商',
       'CNY', 'available', generated_remark, material_group_id, 1, 1, 0,
       now(), 'system', now(), 'system', 0
  from prepared
on conflict (inventory_code) do nothing;

with normalized as (
    select distinct on (inventory_code) *
      from tmp_ecount_inventory_seed
     order by inventory_code, source_row_no
)
update plm_inventory bad
   set deleted_flag = 1,
       remark = case
           when coalesce(bad.remark, '') like '%cleanup_numeric_inventory_after_ecount_seed_20260730%' then bad.remark
           when coalesce(bad.remark, '') = '' then 'cleanup_numeric_inventory_after_ecount_seed_20260730'
           else bad.remark || '; cleanup_numeric_inventory_after_ecount_seed_20260730'
       end,
       updated_at = now(),
       updated_by = 'system'
  from normalized n
 where bad.deleted_flag = 0
   and bad.inventory_code ~ '^[0-9]{3,}$'
   and regexp_replace(bad.inventory_code, '^0+', '') = regexp_replace(coalesce(n.ecount_minor_code, ''), '^0+', '')
   and (bad.inventory_name = n.inventory_name or bad.material_group_id is not null);

with l2_links as (
    select i.inventory_id, parent.material_group_id as parent_material_group_id
      from plm_inventory i
      join plm_material_group child on child.material_group_id = i.material_group_id
       and child.source_system = 'ECOUNT' and child.group_level = 2 and child.deleted_flag = 0
      join plm_material_group parent on parent.material_group_id = child.parent_material_group_id
       and parent.source_system = 'ECOUNT' and parent.group_level = 1 and parent.deleted_flag = 0
     where i.deleted_flag = 0
)
update plm_inventory inventory
   set material_group_id = l2_links.parent_material_group_id,
       updated_at = now(),
       updated_by = 'system'
  from l2_links
 where inventory.inventory_id = l2_links.inventory_id;

update plm_material_group
   set deleted_flag = 1,
       status = 'archived',
       remark = case
           when coalesce(remark, '') like '%archive_ecount_minor_material_groups_20260730%' then remark
           when coalesce(remark, '') = '' then 'archive_ecount_minor_material_groups_20260730'
           else remark || '; archive_ecount_minor_material_groups_20260730'
       end,
       updated_at = now(),
       updated_by = 'system'
 where source_system = 'ECOUNT'
   and deleted_flag = 0
   and (group_level = 2 or ecount_major_code = '0');
